import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from typing import Optional, Dict, Any


class TokenAuthority:
    """Secure token-based authorization system with role-based access control."""

    def __init__(self, signing_key: bytes = None):
        self.signing_key = signing_key or secrets.token_bytes(64)
        self._revocation_list: set = set()
        self._nonce_cache: Dict[str, float] = {}

    def _b64url_encode(self, data: bytes) -> str:
        """RFC 7515 compliant Base64url encoding."""
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _b64url_decode(self, s: str) -> bytes:
        """RFC 7515 compliant Base64url decoding with padding restoration."""
        # Add padding back
        s = s + '=' * (4 - len(s) % 4) if len(s) % 4 != 0 else s
        return base64.urlsafe_b64decode(s.encode('ascii'))

    def _compute_signature(self, signing_input: str) -> str:
        """Compute HMAC-SHA256 signature over the signing input."""
        sig = hmac.new(
            self.signing_key,
            signing_input.encode('utf-8'),
            hashlib.sha256
        ).digest()
        return self._b64url_encode(sig)

    def issue_token(self, user_id: str, roles: list, ttl: int = 3600) -> str:
        """Issue a signed token with claims."""
        header = {"alg": "HS256", "typ": "JWT"}
        now = int(time.time())
        payload = {
            "sub": user_id,
            "roles": roles,
            "iat": now,
            "exp": now + ttl,
            "jti": secrets.token_hex(16)
        }

        header_enc = self._b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_enc = self._b64url_encode(json.dumps(payload, separators=(',', ':')).encode())

        signing_input = f"{header_enc}.{payload_enc}"
        signature = self._compute_signature(signing_input)

        return f"{header_enc}.{payload_enc}.{signature}"

    def _verify_signature(self, token: str) -> bool:
        """Verify the token's HMAC signature."""
        segments = token.split('.')
        if len(segments) != 3:
            return False
        signing_input = f"{segments[0]}.{segments[1]}"
        provided_sig = segments[2]
        expected_sig = self._compute_signature(signing_input)
        return hmac.compare_digest(provided_sig, expected_sig)

    def _extract_claims(self, token: str) -> Optional[Dict[str, Any]]:
        """Extract and parse claims from token payload."""
        segments = token.split('.')
        if len(segments) != 3:
            return None
        try:
            payload_bytes = self._b64url_decode(segments[1])
            claims = json.loads(payload_bytes)
            return claims
        except (ValueError, json.JSONDecodeError):
            return None

    def validate_token(self, token: str) -> Optional[Dict[str, Any]]:
        """Validate token signature and extract claims.

        Security: Verifies HMAC-SHA256 signature before trusting claims.
        Checks expiration and revocation status.
        """
        if not token or not isinstance(token, str):
            return None

        # Verify signature first
        if not self._verify_signature(token):
            return None

        # Extract claims after signature verification
        claims = self._extract_claims(token)
        if claims is None:
            return None

        # Check expiration
        now = int(time.time())
        if claims.get('exp', 0) < now:
            return None

        # Check revocation
        jti = claims.get('jti')
        if jti and jti in self._revocation_list:
            return None

        return claims

    def revoke_token(self, token: str) -> bool:
        """Revoke a token by its JTI."""
        claims = self.validate_token(token)
        if claims and 'jti' in claims:
            self._revocation_list.add(claims['jti'])
            return True
        return False


class ResourceServer:
    """Protected resource server with role-based access control."""

    def __init__(self, token_authority: TokenAuthority):
        self.authority = token_authority
        self._resources: Dict[str, Dict[str, Any]] = {}
        self._audit_log: list = []

    def create_resource(self, token: str, resource_id: str, data: Any) -> bool:
        """Create a resource. Requires 'admin' or 'editor' role."""
        claims = self.authority.validate_token(token)
        if not claims:
            return False

        roles = claims.get('roles', [])
        if not any(r in roles for r in ['admin', 'editor']):
            return False

        self._resources[resource_id] = {
            'data': data,
            'owner': claims['sub'],
            'created_at': int(time.time())
        }
        self._audit_log.append({
            'action': 'create',
            'user': claims['sub'],
            'resource': resource_id,
            'time': int(time.time())
        })
        return True

    def read_resource(self, token: str, resource_id: str) -> Optional[Any]:
        """Read a resource. Requires valid token."""
        claims = self.authority.validate_token(token)
        if not claims:
            return None

        resource = self._resources.get(resource_id)
        if not resource:
            return None

        # Admin can read anything, others only their own
        if 'admin' not in claims.get('roles', []):
            if resource['owner'] != claims['sub']:
                return None

        return resource['data']

    def delete_resource(self, token: str, resource_id: str) -> bool:
        """Delete a resource. Requires 'admin' role."""
        claims = self.authority.validate_token(token)
        if not claims:
            return False

        if 'admin' not in claims.get('roles', []):
            return False

        if resource_id in self._resources:
            del self._resources[resource_id]
            self._audit_log.append({
                'action': 'delete',
                'user': claims['sub'],
                'resource': resource_id,
                'time': int(time.time())
            })
            return True
        return False

    def elevate_privileges(self, token: str, target_user: str, new_roles: list) -> Optional[str]:
        """Issue a new token with elevated privileges. Requires 'admin' role."""
        claims = self.authority.validate_token(token)
        if not claims:
            return None

        if 'admin' not in claims.get('roles', []):
            return None

        return self.authority.issue_token(target_user, new_roles)
